8	export async function total_value_matches_source(ctx: AssertionContext): Promise<AssertionResult> {
9	  const pgResult = await ctx.pg.query("SELECT coalesce(sum(value), 0) AS s FROM raw.events");
10	  const chRows = await queryRows<{ s: number }>(
11	    ctx,
12	    "SELECT sum(s) AS s FROM (SELECT day, sum(total_value) AS s FROM analytics.metric_daily GROUP BY day)",
13	  );
14	  const pgSum = Number(pgResult.rows[0]?.s ?? 0);
15	  const chSum = Number(chRows[0]?.s ?? 0);
16	  const passed = Math.abs(pgSum - chSum) < 0.01;
17	  return {
18	    passed,
19	    message: passed ? "Total value matches source." : `Postgres ${pgSum}, ClickHouse ${chSum}.`,
20	    details: { pgSum, chSum },
21	  };
22	}
