24	export async function all_days_backfilled(ctx: AssertionContext): Promise<AssertionResult> {
25	  const pgResult = await ctx.pg.query(
26	    "SELECT count(DISTINCT date_trunc('day', event_ts)::date) AS n FROM raw.events",
27	  );
28	  const chRows = await queryRows<{ n: number }>(
