30	    "SELECT count() AS n FROM (SELECT day FROM analytics.metric_daily GROUP BY day)",
31	  );
32	  const pgDays = Number(pgResult.rows[0]?.n ?? 0);
33	  const chDays = Number(chRows[0]?.n ?? 0);
